import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { getAuth } from 'firebase/auth'; // Not used in this snippet, but kept for context
import { toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';
import { extractTextFromBase64Data } from '../utils/ocrHelper'; // Corrected import path
import { fileToBase64, getFileType } from '../utils/fileUtils'; // Corrected import path
import { supabase } from './supabaseClient';

const SidePanel = ({ onTextExtracted, userId }) => {
  console.log('User ID received:', userId);
  const [file, setFile] = useState(null);
  const [filesList, setFilesList] = useState([]);
  const [selectedFileUrl, setSelectedFileUrl] = useState(null);
  const [selectedFileType, setSelectedFileType] = useState('');
  const [isProcessingOCR, setIsProcessingOCR] = useState(false);
  const baseUrl = process.env.REACT_APP_API_BASE_URL || 'http://localhost:5000';
  const [extractedText, setExtractedText] = useState('');

  const handleFileChange = (event) => {
    const selected = event.target.files[0];
    if (!selected) return;
    setFile(selected);
  };

 // 📂 Upload directly to Supabase
const handleUpload = async () => {
  if (!file || !userId) {
    toast.error("Please select a file and login first");
    return;
  }

  try {
    const filePath = `${userId}/${file.name}`;

    // Upload file to Supabase bucket
    const { data, error } = await supabase.storage
      .from("user-files")
      .upload(filePath, file, {
        cacheControl: "3600",
        upsert: true, // overwrite if file exists
      });

    if (error) {
      throw error;
    }

    toast.success("File uploaded successfully!");
    setFile(null);

    // ✅ Refresh file list
    fetchFiles(userId);
  } catch (err) {
    console.error("❌ Upload error:", err.message);
    toast.error("Upload failed: " + err.message);
  }
};


const handleDelete = async (filePath) => {
  if (!userId) {
    toast.error("User ID not found. Cannot delete file.");
    return;
  }
  try {
    const { error } = await supabase
      .storage
      .from("user-files")
      .remove([filePath]);

    if (error) throw error;

    toast.success("File deleted successfully");
    fetchFiles(userId);
  } catch (error) {
    console.error("❌ Delete error:", error.message);
    toast.error("Failed to delete file: " + error.message);
  }
};

  // 📂 Fetch
  const fetchFiles = async (uid) => {
    if (!uid) return;

    console.log("Fetching files for:", uid);

    const { data, error } = await supabase
      .storage
      .from("user-files")
      .list(uid);

    if (error) {
      console.error("❌ Fetch error:", error.message);
      return;
    }

    const filesWithUrls = await Promise.all(
      data.map(async (file) => {
        const { data: urlData } = await supabase.storage
          .from("user-files")
          .createSignedUrl(`${uid}/${file.name}`, 60 * 60); // 1 hour
        return {
          name: file.name, // ✅ always include
          path: `${uid}/${file.name}`,
          url: urlData.signedUrl,
        };
      })
    );
    

    console.log("✅ Files fetched with URLs:", filesWithUrls);
    setFilesList(filesWithUrls);
  };

  // ✅ Call fetch on mount or when userId changes
  useEffect(() => {
    if (userId) {
      fetchFiles(userId);
    }
  }, [userId]);

   
  const handleFileClick = (fileItem) => {
    setSelectedFileUrl(fileItem.url);
  
    const ext = fileItem.name.split('.').pop().toLowerCase();
  
    if (['jpg', 'jpeg', 'png'].includes(ext)) {
      setSelectedFileType('image');
    } 
    else if (ext === 'pdf') {
      setSelectedFileType('pdf');
    } 
    else if (['doc', 'docx', 'ppt', 'pptx', 'xls', 'xlsx'].includes(ext)) {
      setSelectedFileType('office');   // ⭐ NEW
    } 
    else {
      setSelectedFileType('unknown');
    }
  };
  
    
  
  


  const saveExtractedText = async (textToSave) => {
    if (!userId || !textToSave) return; // Ensure userId and text are present
    try {
      // Use a new endpoint for saving/updating text associated with the user
      await axios.post(`${baseUrl}/api/extracted-text`, { userId, text: textToSave });
    } catch (error) {
      console.error('❌ Failed to save text:', error);
      toast.error('Failed to save extracted text.');
    }
  };

  const deleteExtractedText = async () => {
    if (!userId) return;
    try {
      await axios.delete(`${baseUrl}/api/extracted-text/${userId}`);
      setExtractedText(''); // Clear the extracted text from state
      onTextExtracted(''); // Clear text on the whiteboard as well
      toast.success("Extracted text deleted successfully.");
    } catch (error) {
      console.error('❌ Failed to delete text:', error);
      toast.error('Failed to delete extracted text.');
    }
  };

  const fetchExtractedText = async () => {
    if (!userId) return;
    try {
      // Fetch the saved text for the current user
      const response = await axios.get(`${baseUrl}/api/extracted-text/${userId}`);
      if (response.data && response.data.text) {
        setExtractedText(response.data.text);
        // Pass the loaded text to the whiteboard on load
        onTextExtracted(response.data.text);
      }
    } catch (error) {
      // It's normal for this to fail if no text has been saved yet, so log as info
      console.info('No extracted text found for user:', userId);
    }
  };

  const handleOCR = async () => {
    // Initial check for a file
    if (!file) {
      toast.warn("Please select a file using 'Choose File' button to perform OCR.");
      return;
    }
    const fileToProcess = file;
    const type = getFileType(fileToProcess); // This will return 'image' or 'pdf'

    if (type !== 'image' && type !== 'pdf') {
      toast.error('OCR only supports image (PNG, JPG) or PDF files.');
      return;
    }

    setIsProcessingOCR(true);
    toast.info("Processing OCR...");

    try {
      const base64Data = await fileToBase64(fileToProcess);
      const extractedTextResult = await extractTextFromBase64Data(base64Data, type);

      if (extractedTextResult) {
        setExtractedText(extractedTextResult);
        onTextExtracted(extractedTextResult); // Send to whiteboard
        toast.success("Text extracted and sent to whiteboard!");
        await saveExtractedText(extractedTextResult); // Save to backend
      } else {
        toast.info("No text could be extracted from this file.");
      }
    } catch (error) {
      console.error('OCR failed:', error);
      toast.error(`OCR failed: ${error.message}. Check browser console and backend logs.`);
    } finally {
      setIsProcessingOCR(false);
      setFile(null);
      document.querySelector('input[type="file"]').value = '';
    }
  };



  useEffect(() => {
    fetchExtractedText();
  }, [userId]);

  // Effect to debounce saving of edited extracted text
  useEffect(() => {
    if (extractedText) {
      const handler = setTimeout(() => {
        saveExtractedText(extractedText);
      }, 1000); // Wait 1 second after the user stops typing before saving
      return () => {
        clearTimeout(handler);
      };
    }
  }, [extractedText, userId]);


  return (
   <div
  style={{
    position: 'fixed',
    top: 0,
    left: 0,
    width: '340px',
    height: '100vh',
    backgroundColor: '#010141',
    color: '#fff',
    padding: '16px',
    display: 'block', // ✅ no need for flex when scrolling entire panel
    boxSizing: 'border-box',
    borderRight: '1px solid #ccc',
    borderTopRightRadius: '16px',
    borderBottomRightRadius: '16px',
    overflowY: 'auto',   // ✅ enables full panel scroll
    overflowX: 'hidden',
    zIndex: 30, // ✅ TopToolbar/WhiteboardToolbar (z-50) ke peeche rehne ke liye
  }}
>


      <h4 style={{ marginBottom: '10px', fontSize: '18px', color: '#ffffff' }}>
        Attach File
      </h4>

      <label
        htmlFor="file-upload"
        style={{
          display: 'block',
          width: '100%',
          padding: '6px 12px',
          backgroundColor: '#fff',
          color: '#000',
          borderRadius: '4px',
          fontSize: '13px',
          textAlign: 'center',
          cursor: 'pointer',
          marginBottom: '10px',
          border: '1px solid #ccc',
        }}
      >
        Choose File
      </label>
      <input
        id="file-upload"
        type="file"
        onChange={handleFileChange}
        style={{
          display: 'none',
        }}
      />

      {file && (
        <p style={{ fontSize: '12px', color: '#ccc', marginBottom: '10px' }}>
          Selected: {file.name}
        </p>
      )}

      <div style={{ display: 'flex', gap: '10px', marginBottom: '20px' }}>
        <button
          onClick={handleUpload}
          style={{
            fontSize: '13px',
            padding: '6px 12px',
            backgroundColor: '#4A90E2',
            color: 'white',
            border: 'none',
            borderRadius: '6px',
            cursor: 'pointer',
            flex: 1,
          }}
        >
          Upload
        </button>
        <button
          onClick={handleOCR}
          disabled={isProcessingOCR || !file}
          style={{
            fontSize: '13px',
            padding: '6px 12px',
            backgroundColor: isProcessingOCR ? '#888' : '#28A745',
            color: 'white',
            border: 'none',
            borderRadius: '6px',
            cursor: isProcessingOCR ? 'not-allowed' : 'pointer',
            flex: 1,
          }}
        >
          {isProcessingOCR ? 'Processing...' : 'Extract Text'}
        </button>
      </div>

      <h4 style={{ marginBottom: '10px', fontSize: '16px', color: '#ffffff' }}>
  Uploaded Files
</h4>
      <ul
        style={{
          listStyle: 'none',
          padding: '6px 10px',
          backgroundColor: '#ffffff',
          borderRadius: '6px',
          color: '#000',
          
        }}
      >
        {Array.isArray(filesList) && filesList.length > 0 ? (
          filesList.map((fileItem, index) => (
            <li
              key={fileItem.id || index}
              style={{
                marginBottom: '6px',
                display: 'flex',
                justifyContent: 'space-between',
                alignItems: 'center',
                gap: '6px',
                wordBreak: 'break-all',
              }}
            >
             <button
  onClick={() => handleFileClick(fileItem)}
  style={{
    background: 'none',
    border: 'none',
    color: '#010141',
    cursor: 'pointer',
    fontSize: '13px',
    textAlign: 'left',
    flex: 1,
    overflow: 'hidden',
    textOverflow: 'ellipsis',
    whiteSpace: 'nowrap',
  }}
  title={
    fileItem.filename 
      || fileItem.name 
      || (fileItem.filePath ? fileItem.filePath.split('/').pop() : 'Unknown')
  }  >
   {fileItem.filename 
    || fileItem.name 
    || (fileItem.filePath ? fileItem.filePath.split('/').pop() : 'Unnamed File')}
</button>


<button
  onClick={() => handleDelete(fileItem.path)}
  style={{
    color: 'red',
    fontSize: '12px',
    border: 'none',
    background: 'none',
    cursor: 'pointer',
  }}
>
  🗑
</button>

            </li>
          ))
        ) : (
          <li style={{ color: '#888', fontSize: '12px' }}>No files uploaded yet.</li>
        )}
      </ul>
      {selectedFileUrl && (
  <div
    style={{
      marginTop: '20px',
      height: '300px',              // fixed height
      overflowY: 'auto',            // make scrollable
      backgroundColor: '#fff',
      borderRadius: '6px',
      padding: '8px',
      border: '1px solid #ccc',
      display: 'flex',
      flexDirection: 'column',
    }}
  >
    <h5
      style={{
        fontSize: '14px',
        marginBottom: '8px',
        color: '#000',
        flexShrink: 0, // prevent heading from shrinking
      }}
    >
      Preview
    </h5>

    <div
      style={{
        flex: 1,
        overflowY: 'auto', // ✅ scrolling applies here
        borderRadius: '4px',
      }}
    >
      {selectedFileType === 'image' && (
  <img
    src={selectedFileUrl}
    alt="Preview"
    style={{ width: '100%', borderRadius: '6px' }}
  />
)}

{selectedFileType === 'pdf' && (
  <iframe
    src={`https://mozilla.github.io/pdf.js/web/viewer.html?file=${encodeURIComponent(selectedFileUrl)}`}
    width="100%"
    height="100%"
    title="PDF Preview"
    style={{ border: 'none', borderRadius: '6px' }}
  />
)}


{selectedFileType === 'office' && (
  <iframe
    src={`https://view.officeapps.live.com/op/embed.aspx?src=${encodeURIComponent(selectedFileUrl)}`}
    width="100%"
    height="100%"
    title="Office Preview"
    style={{ border: 'none', borderRadius: '6px' }}
  />
)}


{selectedFileType === 'unknown' && (
  <p style={{ fontSize: '12px', color: '#000' }}>
    Not previewable.{' '}
    <a
      href={selectedFileUrl}
      target="_blank"
      rel="noopener noreferrer"
      style={{ color: '#4A90E2' }}
    >
      Download
    </a>
  </p>
)}

    </div>
  </div>
)}

      {extractedText && (
        <div
          ref={(ref) => (window.extractedBox = ref)}
          style={{
            position: 'fixed',
            top: '100px',
            left: '350px',
            zIndex: 30,
            width: '400px',
            height: '240px',
            backgroundColor: '#f9f9f9',
            border: '2px solid #ccc',
            borderRadius: '8px',
            padding: '12px',
            cursor: 'move',
            boxShadow: '0 4px 10px rgba(0,0,0,0.15)',
            color: '#000',
            resize: 'both',
            overflow: 'hidden',
            display: 'flex',
            flexDirection: 'column',
          }}
          onMouseDown={(e) => {
            const box = e.currentTarget;
            if (e.target.closest('.resize-handle') || e.target.tagName === 'TEXTAREA' || e.target.classList.contains('close-btn')) return;
            const shiftX = e.clientX - box.getBoundingClientRect().left;
            const shiftY = e.clientY - box.getBoundingClientRect().top;
            function moveAt(pageX, pageY) {
              const screenW = window.innerWidth;
              const screenH = window.innerHeight;
              const boxW = box.offsetWidth;
              const boxH = box.offsetHeight;
              let newLeft = pageX - shiftX;
              let newTop = pageY - shiftY;
              newLeft = Math.max(0, Math.min(newLeft, screenW - boxW));
              newTop = Math.max(0, Math.min(newTop, screenH - boxH));
              box.style.left = newLeft + 'px';
              box.style.top = newTop + 'px';
            }
            function onMouseMove(e) {
              moveAt(e.pageX, e.pageY);
            }
            document.addEventListener('mousemove', onMouseMove);
            document.onmouseup = () => {
              document.removeEventListener('mousemove', onMouseMove);
              document.onmouseup = null;
            };
          }}
        >
          <button
            className="close-btn"
            onClick={(e) => {
              e.preventDefault();
              deleteExtractedText(); // Call the new function to delete from Firestore
            }}
            style={{
              position: 'absolute',
              top: '6px',
              right: '6px',
              background: 'transparent',
              border: 'none',
              fontSize: '16px',
              cursor: 'pointer',
              color: '#333',
              fontWeight: 'bold',
            }}
          >
            ❌
          </button>
          <h5 style={{ fontSize: '15px', marginBottom: '8px', fontWeight: 'bold' }}>Extracted Text</h5>
          <textarea
            value={extractedText}
            onChange={(e) => setExtractedText(e.target.value)}
            style={{
              width: '100%',
              height: 'calc(100% - 50px)',
              resize: 'none',
              padding: '8px',
              fontSize: '13px',
              borderRadius: '4px',
              border: '1px solid #aaa',
              backgroundColor: '#fff',
              fontFamily: 'monospace',
              color: '#000',
              boxSizing: 'border-box',
            }}
          />
        </div>
      )}
    </div>
  );
};

export default SidePanel;
